{
  "name": "ponytail-on-stimulants-pi-extension-dev",
  "private": true,
  "type": "module",
  "scripts": {
    "test": "node --import ../tests/isolate-recaps.cjs --test ./test/*.test.js"
  }
}

'use strict';

const crypto = require('crypto');

const MODE_POLICIES = Object.freeze({
  off: { maxContinuations: 0 },
  focused: { maxContinuations: 0 },
  'full-send': { maxContinuations: 1 },
  feral: { maxContinuations: 2 },
});

const MUTATION_TOOLS = new Set([
  'edit',
  'write',
  'strreplace',
  'str_replace',
  'notebookedit',
  'notebook_edit',
  'apply_patch',
  'applypatch',
]);
const SEARCH_TOOLS = new Set(['grep', 'find', 'read', 'ls', 'glob']);
const EXECUTION_WORDS = /\b(add|address|build|change|complete|configure|create|debug|delete|disable|enable|finish|fix|handle|implement|install|make|migrate|modify|refactor|remove|rename|repair|resolve|rework|run|ship|support|take care of|test|update|upgrade|verify|write)\b/i;
const INFORMATIONAL_ONLY = /^\s*(explain|how|what|when|where|which|who|why)\b/i;
const TODO_PATTERN = /^\+[^+].*\b(TODO|FIXME|XXX|HACK)\b/im;
const TODO_TEXT = /\b(TODO|FIXME|XXX|HACK)\b/i;

function canonicalToolName(toolName) {
  return String(toolName || 'unknown').trim().toLowerCase() || 'unknown';
}

function mutationKey(toolName) {
  return canonicalToolName(toolName).replace(/[^a-z0-9]/g, '');
}

function isMutationTool(toolName) {
  const name = canonicalToolName(toolName);
  if (MUTATION_TOOLS.has(name)) return true;
  const key = mutationKey(name);
  return key === 'edit' || key === 'write' || key === 'strreplace' ||
    key === 'notebookedit' || key === 'applypatch';
}

function isContinuationPrompt(text) {
  return /\bPONYTAIL ON STIMULANTS COMPLETION PASS\b/.test(String(text || ''));
}

function hash(value) {
  return crypto.createHash('sha256').update(String(value)).digest('hex').slice(0, 16);
}

function stableStringify(value) {
  if (!value || typeof value !== 'object') return JSON.stringify(value);
  if (Array.isArray(value)) return `[${value.map(stableStringify).join(',')}]`;
  return `{${Object.keys(value).sort().map((key) => `${JSON.stringify(key)}:${stableStringify(value[key])}`).join(',')}}`;
}

function fingerprintTool(toolName, args) {
  return `${toolName}:${hash(stableStringify(args || {}))}`;
}

function redact(value) {
  return String(value || '')
    .replace(/(["']?[a-z0-9_-]*(?:api[_-]?key|token|password|secret)["']?\s*[:=]\s*)(?:"[^"]*"|'[^']*'|[^\s,}]+)/gi, '$1[redacted]')
    .replace(/(--?[a-z0-9_-]*(?:api[_-]?key|token|password|secret))\s+(?:"[^"]*"|'[^']*'|\S+)/gi, '$1 [redacted]')
    .replace(/\bBearer\s+[^\s]+/gi, 'Bearer [redacted]')
    .replace(/\b(?:gh[pousr]_[a-z0-9_]{20,}|sk-[a-z0-9_-]{16,})\b/gi, '[redacted]');
}

function actionSummary(toolName, args = {}) {
  const value = toolName === 'bash' ? args.command :
    toolName === 'grep' ? `${args.pattern || ''} ${args.path || ''}`.trim() :
    args.path || args.file_path || '';
  return redact(value).slice(0, 300);
}

function isExecutionPrompt(text) {
  const prompt = String(text || '').trim();
  if (!prompt || INFORMATIONAL_ONLY.test(prompt)) return false;
  return EXECUTION_WORDS.test(prompt);
}

function createTurnState(prompt = '') {
  return {
    prompt: String(prompt || ''),
    acceptedExecution: isExecutionPrompt(prompt),
    continuations: 0,
    toolCalls: 0,
    hadMutation: false,
    recentTools: [],
    pendingTools: new Map(),
    fingerprints: new Map(),
    failureCounts: new Map(),
    unresolvedFailures: new Map(),
    lastPrompt: null,
    recapped: false,
    answer: '',
  };
}

function recordToolCall(state, toolName, args, toolCallId) {
  if (!state) return null;
  const name = canonicalToolName(toolName);
  const fingerprint = fingerprintTool(name, args);
  const entry = {
    tool: name,
    action: actionSummary(name, args),
    fingerprint,
    status: 'pending',
  };
  state.toolCalls += 1;
  state.recentTools.push(entry);
  if (state.recentTools.length > 20) state.recentTools.shift();
  if (toolCallId) state.pendingTools.set(toolCallId, { args, entry, fingerprint });
  if (isMutationTool(name)) state.hadMutation = true;
  state.fingerprints.set(fingerprint, (state.fingerprints.get(fingerprint) || 0) + 1);
  return fingerprint;
}

function resolveToolResult(state, toolName, args, toolCallId) {
  const name = canonicalToolName(toolName);
  const pending = toolCallId ? state.pendingTools.get(toolCallId) : null;
  const resolvedArgs = pending?.args || args || {};
  const fingerprint = pending?.fingerprint || fingerprintTool(name, resolvedArgs);
  const entry = pending?.entry || [...state.recentTools].reverse()
    .find((item) => item.fingerprint === fingerprint && item.status === 'pending');
  if (toolCallId) state.pendingTools.delete(toolCallId);
  return { entry, fingerprint, resolvedArgs };
}

function recordToolResult(state, toolName, args, isError, toolCallId) {
  if (!state) return;
  const { entry, fingerprint, resolvedArgs } = resolveToolResult(state, toolName, args, toolCallId);
  if (isError === null) {
    if (entry) entry.status = 'unknown';
    return; // An observed result without a reliable outcome proves no success.
  }
  if (entry) entry.status = isError ? 'failed' : 'passed';
  if (!isError) {
    state.unresolvedFailures.delete(fingerprint);
    return;
  }
  const failure = { tool: toolName, action: actionSummary(toolName, resolvedArgs), fingerprint };
  state.unresolvedFailures.set(fingerprint, failure);
  state.failureCounts.set(fingerprint, (state.failureCounts.get(fingerprint) || 0) + 1);
}

function summarizeTrackedEvidence(state) {
  const repeatedActions = [...state.fingerprints.entries()]
    .filter(([, count]) => count > 1)
    .map(([fingerprint, count]) => ({ fingerprint, count }));
  const repeatedFailures = [...state.failureCounts.entries()]
    .filter(([, count]) => count > 1)
    .map(([fingerprint, count]) => ({ fingerprint, count }));
  return {
    acceptedExecution: state.acceptedExecution,
    hadMutation: state.hadMutation,
    toolCalls: state.toolCalls,
    toolErrors: [...state.unresolvedFailures.values()].slice(-8),
    recentTools: state.recentTools.slice(-20),
    repeatedActions: repeatedActions.slice(-8),
    repeatedFailures: repeatedFailures.slice(-8),
  };
}

function emptyGitEvidence() {
  return {
    available: false,
    changedFiles: [],
    diffCheckFailed: false,
    introducedTodos: [],
    errors: [],
  };
}

function recordStatus(evidence, status) {
  if (status.code !== 0) {
    evidence.errors.push('git status failed');
    return;
  }
  evidence.changedFiles = String(status.stdout || '')
    .split(/\r?\n/)
    .filter(Boolean)
    .map((line) => line.slice(3).trim())
    .slice(0, 100);
}

function recordDiffChecks(evidence, checks) {
  for (const check of checks) {
    if (check.code === 0) continue;
    evidence.diffCheckFailed = true;
    evidence.errors.push(String(check.stderr || check.stdout || 'git diff --check failed').trim().slice(0, 500));
  }
}

function trackedTodos(diffs) {
  const todos = [];
  for (const diff of diffs.filter((item) => item.code === 0)) {
    for (const line of String(diff.stdout || '').split(/\r?\n/)) {
      if (TODO_PATTERN.test(`${line}\n`)) todos.push(line.slice(1).trim());
    }
  }
  return todos;
}

async function untrackedTodos(git, untracked, evidence) {
  if (untracked.code !== 0) {
    evidence.errors.push('git untracked-file scan failed');
    return [];
  }
  const paths = String(untracked.stdout || '').split(/\r?\n/).filter(Boolean).slice(0, 100);
  if (paths.length === 0) return [];
  const grep = await git(['grep', '--no-index', '-n', '-I', '-E', 'TODO|FIXME|XXX|HACK', '--', ...paths]);
  if (grep.code === 0) return String(grep.stdout || '').split(/\r?\n/).filter((line) => TODO_TEXT.test(line));
  if (grep.code > 1) evidence.errors.push('untracked TODO scan failed');
  return [];
}

async function collectGitEvidence(exec, cwd) {
  const evidence = emptyGitEvidence();
  if (typeof exec !== 'function') return evidence;

  async function git(args) {
    try {
      return await exec('git', args, { cwd, timeout: 5000 });
    } catch (error) {
      return { code: 1, stdout: '', stderr: String(error && error.message || error) };
    }
  }

  const inside = await git(['rev-parse', '--is-inside-work-tree']);
  if (inside.code !== 0 || String(inside.stdout).trim() !== 'true') return evidence;
  evidence.available = true;
  const [status, worktreeCheck, stagedCheck, worktreeDiff, stagedDiff, untracked] = await Promise.all([
    git(['status', '--porcelain']),
    git(['diff', '--check']),
    git(['diff', '--cached', '--check']),
    git(['diff', '--unified=0', '--no-ext-diff']),
    git(['diff', '--cached', '--unified=0', '--no-ext-diff']),
    git(['ls-files', '--others', '--exclude-standard']),
  ]);
  recordStatus(evidence, status);
  recordDiffChecks(evidence, [worktreeCheck, stagedCheck]);
  const todos = trackedTodos([worktreeDiff, stagedDiff]);
  todos.push(...await untrackedTodos(git, untracked, evidence));
  evidence.introducedTodos = [...new Set(todos)].slice(0, 20);
  return evidence;
}

function maxContinuations(mode) {
  return (MODE_POLICIES[mode] || MODE_POLICIES['full-send']).maxContinuations;
}

function shouldRunCompletionPass(mode, state, evidence = {}) {
  const maximum = maxContinuations(mode);
  if (!state || maximum === 0 || state.continuations >= maximum) return false;
  const tracked = evidence.tracked || summarizeTrackedEvidence(state);
  // A dirty worktree may predate this turn; never treat it alone as agent work.
  return Boolean(
    tracked.hadMutation ||
    (tracked.acceptedExecution && (tracked.toolCalls > 0 || (tracked.toolErrors || []).length > 0)),
  );
}

function compactEvidence(evidence) {
  const tracked = evidence.tracked || {};
  const git = evidence.git || {};
  return {
    git_available: Boolean(git.available),
    git_errors: (git.errors || []).slice(0, 5),
    changed_files: (git.changedFiles || []).slice(0, 30),
    diff_check_failed: Boolean(git.diffCheckFailed),
    introduced_todos: (git.introducedTodos || []).slice(0, 10),
    tool_error_count: (tracked.toolErrors || []).length,
    recent_actions: (tracked.recentTools || []).slice(-10),
    repeated_actions: (tracked.repeatedActions || []).slice(0, 5),
    repeated_failures: (tracked.repeatedFailures || []).slice(0, 5),
  };
}

function buildContinuationPrompt({ mode, pass, maximum, evidence, jev }) {
  const compact = compactEvidence(evidence);
  const lines = [
    `PONYTAIL ON STIMULANTS COMPLETION PASS ${pass}/${maximum} (${mode}).`,
    'Do not merely reaffirm completion. Inspect the repository and finish any directly necessary or mechanically implied work.',
    'Re-check callers and sibling paths, edge cases, generated/derived state, failed commands, relevant verification, the final diff, and accidental files.',
    `Deterministic evidence: ${JSON.stringify(compact)}`,
  ];
  if (jev && jev.verdict && jev.verdict !== 'unavailable') {
    lines.push(`Optional Jev judgment: ${JSON.stringify({ verdict: jev.verdict, answers: jev.answers })}`);
  }
  lines.push('If everything is truly complete, state the concrete evidence briefly. Otherwise perform the remaining work now. Keep scope bounded.');
  return lines.join('\n');
}

function claimContinuation(state, prompt, maximum) {
  if (!state || !prompt || state.lastPrompt === prompt) return false;
  if (!Number.isInteger(maximum) || maximum < 0 || state.continuations >= maximum) return false;
  state.continuations += 1;
  state.lastPrompt = prompt;
  return true;
}

function serializeTurnState(state) {
  const snapshot = state || createTurnState('');
  return {
    prompt: snapshot.prompt,
    acceptedExecution: Boolean(snapshot.acceptedExecution),
    continuations: snapshot.continuations || 0,
    toolCalls: snapshot.toolCalls || 0,
    hadMutation: Boolean(snapshot.hadMutation),
    recentTools: Array.isArray(snapshot.recentTools) ? snapshot.recentTools.slice(-20) : [],
    pendingTools: [...(snapshot.pendingTools || new Map()).entries()].map(([id, pending]) => [
      id,
      {
        args: pending && pending.args || {},
        fingerprint: pending && pending.fingerprint,
        entry: pending && pending.entry,
      },
    ]),
    fingerprints: [...(snapshot.fingerprints || new Map()).entries()],
    failureCounts: [...(snapshot.failureCounts || new Map()).entries()],
    unresolvedFailures: [...(snapshot.unresolvedFailures || new Map()).entries()],
    lastPrompt: snapshot.lastPrompt || null,
    recapped: Boolean(snapshot.recapped),
    answer: typeof snapshot.answer === 'string' ? snapshot.answer : '',
  };
}

function restoreMap(value) {
  try {
    return new Map(Array.isArray(value) ? value : []);
  } catch (_) {
    return new Map();
  }
}

function restoreTurnState(raw) {
  const state = createTurnState(raw && raw.prompt);
  if (!raw || typeof raw !== 'object') return state;
  state.acceptedExecution = Boolean(raw.acceptedExecution);
  state.continuations = Number.isInteger(raw.continuations) && raw.continuations >= 0 ? raw.continuations : 0;
  state.toolCalls = Number.isInteger(raw.toolCalls) && raw.toolCalls >= 0 ? raw.toolCalls : 0;
  state.hadMutation = Boolean(raw.hadMutation);
  state.recentTools = Array.isArray(raw.recentTools) ? raw.recentTools.slice(-20) : [];
  state.lastPrompt = typeof raw.lastPrompt === 'string' ? raw.lastPrompt : null;
  state.recapped = Boolean(raw.recapped);
  state.answer = typeof raw.answer === 'string' ? raw.answer : '';
  state.fingerprints = restoreMap(raw.fingerprints);
  state.failureCounts = restoreMap(raw.failureCounts);
  state.unresolvedFailures = restoreMap(raw.unresolvedFailures);
  state.pendingTools = restoreMap(raw.pendingTools);
  for (const [id, pending] of state.pendingTools) {
    if (!pending || typeof pending !== 'object') {
      state.pendingTools.delete(id);
      continue;
    }
    const fingerprint = pending.fingerprint || (pending.entry && pending.entry.fingerprint);
    const entry = state.recentTools.find((item) => item && item.fingerprint === fingerprint && item.status === 'pending')
      || pending.entry
      || null;
    if (entry) pending.entry = entry;
    pending.fingerprint = fingerprint;
  }
  return state;
}

function createSpawnExec(spawnSyncImpl) {
  const spawnSync = spawnSyncImpl || require('child_process').spawnSync;
  return async function exec(command, args, options = {}) {
    try {
      const result = spawnSync(command, args, {
        cwd: options.cwd,
        timeout: options.timeout || 5000,
        encoding: 'utf8',
        windowsHide: true,
      });
      if (result.error) {
        return {
          code: 1,
          stdout: result.stdout || '',
          stderr: String(result.error.message || result.error),
        };
      }
      return {
        code: typeof result.status === 'number' ? result.status : 1,
        stdout: result.stdout || '',
        stderr: result.stderr || '',
      };
    } catch (error) {
      return { code: 1, stdout: '', stderr: String(error && error.message || error) };
    }
  };
}

async function runCompletionDecision({ mode, state, exec, cwd, jev = null }) {
  const tracked = summarizeTrackedEvidence(state);
  if (!shouldRunCompletionPass(mode, state, { tracked })) return null;
  const git = typeof exec === 'function' ? await collectGitEvidence(exec, cwd) : emptyGitEvidence();
  const evidence = { tracked, git };
  const maximum = maxContinuations(mode);
  const prompt = buildContinuationPrompt({
    mode,
    pass: state.continuations + 1,
    maximum,
    evidence,
    jev,
  });
  if (!claimContinuation(state, prompt, maximum)) return null;
  return {
    prompt,
    evidence,
    compact: compactEvidence(evidence),
    pass: state.continuations,
    maximum,
  };
}

module.exports = {
  MODE_POLICIES,
  SEARCH_TOOLS,
  buildContinuationPrompt,
  canonicalToolName,
  claimContinuation,
  collectGitEvidence,
  compactEvidence,
  createSpawnExec,
  createTurnState,
  fingerprintTool,
  isContinuationPrompt,
  isExecutionPrompt,
  isMutationTool,
  maxContinuations,
  recordToolCall,
  recordToolResult,
  redact,
  restoreTurnState,
  runCompletionDecision,
  serializeTurnState,
  shouldRunCompletionPass,
  summarizeTrackedEvidence,
};

#!/usr/bin/env node
'use strict';

const fs = require('node:fs');
const os = require('node:os');
const path = require('node:path');
const readline = require('node:readline');

const ROOT = path.resolve(__dirname, '..');
const SKILL_PATH = path.join(ROOT, 'skills', 'ponytail-on-stimulants', 'SKILL.md');
const MODES = Object.freeze(['focused', 'full-send', 'feral']);
const DEFAULT_MODE = 'full-send';
const PROTOCOL_VERSION = '2024-11-05';
const SERVER_NAME = 'ponytail-on-stimulants';
const TOOL_NAME = 'ponytail_on_stimulants_instructions';
const VERSION = JSON.parse(fs.readFileSync(path.join(ROOT, 'plugin.json'), 'utf8')).version;

function canonicalMode(value) {
  return typeof value === 'string' && MODES.includes(value.trim().toLowerCase())
    ? value.trim().toLowerCase()
    : null;
}

function configPath() {
  if (process.env.PLUGIN_DATA) {
    return path.join(process.env.PLUGIN_DATA, 'config.json');
  }
  if (process.env.XDG_CONFIG_HOME) {
    return path.join(process.env.XDG_CONFIG_HOME, SERVER_NAME, 'config.json');
  }
  if (process.platform === 'win32') {
    const base = process.env.APPDATA || path.join(os.homedir(), 'AppData', 'Roaming');
    return path.join(base, SERVER_NAME, 'config.json');
  }
  return path.join(os.homedir(), '.config', SERVER_NAME, 'config.json');
}

function configuredMode() {
  const fromEnvironment = canonicalMode(process.env.PONYTAIL_ON_STIMULANTS_DEFAULT_MODE);
  if (fromEnvironment) return fromEnvironment;
  try {
    const config = JSON.parse(fs.readFileSync(configPath(), 'utf8'));
    return canonicalMode(config && config.defaultMode) || DEFAULT_MODE;
  } catch (_) {
    return DEFAULT_MODE;
  }
}

function resolveMode(value) {
  return value === undefined ? configuredMode() : canonicalMode(value);
}

function stripFrontmatter(text) {
  return String(text || '').replace(/^---[\s\S]*?---\s*/, '');
}

function filterSkillBody(body, mode) {
  return stripFrontmatter(body)
    .split(/\r?\n/)
    .filter((line) => {
      const table = line.match(/^\|\s*\*\*(.+?)\*\*\s*\|/);
      if (table && MODES.includes(table[1].trim())) return table[1].trim() === mode;
      const example = line.match(/^-\s*([^:]+):\s*"/);
      if (example && MODES.includes(example[1].trim())) return example[1].trim() === mode;
      return true;
    })
    .join('\n');
}

function buildInstructions(mode) {
  try {
    const body = fs.readFileSync(SKILL_PATH, 'utf8');
    return `PONYTAIL ON STIMULANTS ACTIVE — mode: ${mode}\n\n${filterSkillBody(body, mode)}`;
  } catch (_) {
    return `PONYTAIL ON STIMULANTS ACTIVE — mode: ${mode}\n\n` +
      'Minimal architecture. Maximal execution. Finish the requested outcome, verify it proportionately, and keep scope bounded.';
  }
}

const modeSchema = {
  type: 'string',
  enum: MODES,
  description: 'Execution mode. Omit to use the configured default.',
};

const prompt = {
  name: SERVER_NAME,
  description: 'Minimal architecture, maximal execution instructions.',
  arguments: [{ name: 'mode', description: modeSchema.description, required: false }],
};

const tool = {
  name: TOOL_NAME,
  description: 'Return the completion ruleset for focused, full-send, or feral mode.',
  inputSchema: {
    type: 'object',
    properties: { mode: modeSchema },
    additionalProperties: false,
  },
};

function result(id, value) {
  return { jsonrpc: '2.0', id, result: value };
}

function error(id, code, message) {
  return { jsonrpc: '2.0', id: id ?? null, error: { code, message } };
}

function requestedMode(params, field) {
  const values = params && params[field];
  if (values === undefined) return configuredMode();
  if (!values || typeof values !== 'object' || Array.isArray(values)) return null;
  if (Object.keys(values).some((key) => key !== 'mode')) return null;
  return resolveMode(values.mode);
}

function invalidMode(id) {
  return error(id, -32602, `mode must be one of: ${MODES.join(', ')}`);
}

function isObject(value) {
  return value !== null && typeof value === 'object' && !Array.isArray(value);
}

function validRequestId(id) {
  return typeof id === 'string' || (typeof id === 'number' && Number.isInteger(id));
}

function validInitializeParams(params) {
  return isObject(params)
    && typeof params.protocolVersion === 'string'
    && isObject(params.capabilities)
    && isObject(params.clientInfo)
    && typeof params.clientInfo.name === 'string'
    && typeof params.clientInfo.version === 'string';
}

function initialize(id, params) {
  if (!validInitializeParams(params)) return error(id, -32602, 'Invalid initialize parameters');
  return result(id, {
    protocolVersion: PROTOCOL_VERSION,
    capabilities: { prompts: { listChanged: false }, tools: { listChanged: false } },
    serverInfo: { name: SERVER_NAME, version: VERSION },
  });
}

function getPrompt(id, params) {
  if (!params || params.name !== SERVER_NAME) return error(id, -32602, 'Unknown prompt');
  const mode = requestedMode(params, 'arguments');
  if (!mode) return invalidMode(id);
  return result(id, {
    description: prompt.description,
    messages: [{ role: 'user', content: { type: 'text', text: buildInstructions(mode) } }],
  });
}

function callTool(id, params) {
  if (!params || params.name !== TOOL_NAME) return error(id, -32602, 'Unknown tool');
  const mode = requestedMode(params, 'arguments');
  if (!mode) return invalidMode(id);
  const instructions = buildInstructions(mode);
  return result(id, {
    content: [{ type: 'text', text: instructions }],
  });
}

const handlers = new Map([
  ['initialize', initialize],
  ['ping', (id) => result(id, {})],
  ['prompts/list', (id) => result(id, { prompts: [prompt] })],
  ['prompts/get', getPrompt],
  ['tools/list', (id) => result(id, { tools: [tool] })],
  ['tools/call', callTool],
]);

let lifecycle = 'uninitialized';

function invalidEnvelope(message) {
  if (!isObject(message) || message.jsonrpc !== '2.0' || typeof message.method !== 'string') return true;
  return Object.hasOwn(message, 'id') && !validRequestId(message.id);
}

function dispatchNotification(method) {
  if (method === 'notifications/initialized' && lifecycle === 'initializing') lifecycle = 'ready';
}

function dispatch(message) {
  if (invalidEnvelope(message)) return error(null, -32600, 'Invalid Request');
  const { method, params } = message;
  const isNotification = !Object.hasOwn(message, 'id');
  if (isNotification) {
    dispatchNotification(method);
    return undefined;
  }
  const { id } = message;
  if (method.startsWith('notifications/')) return error(id, -32600, 'Invalid Request');
  if (method === 'initialize') {
    if (lifecycle !== 'uninitialized') return error(id, -32600, 'Already initialized');
    const response = initialize(id, params);
    if (response.result) lifecycle = 'initializing';
    return response;
  }
  if (lifecycle !== 'ready') return error(id, -32002, 'Server not initialized');
  const handler = handlers.get(method);
  return handler ? handler(id, params) : error(id, -32601, 'Method not found');
}

function send(message) {
  if (message !== undefined) process.stdout.write(`${JSON.stringify(message)}\n`);
}

const lines = readline.createInterface({ input: process.stdin, crlfDelay: Infinity, terminal: false });
lines.on('line', (line) => {
  if (!line.trim()) return;
  try {
    send(dispatch(JSON.parse(line)));
  } catch (_) {
    send(error(null, -32700, 'Parse error'));
  }
});

import { createRequire } from 'node:module';

const require = createRequire(import.meta.url);
const {
  DEFAULT_MODE,
  RUNTIME_MODES,
  getDefaultMode,
  getQuietStartup,
  getHideStatus,
  normalizeMode,
  isDeactivationCommand,
  writeDefaultMode,
} = require('../hooks/ponytail-on-stimulants-config.js');
const {
  getPonytailInstructions,
  filterSkillBodyForMode,
} = require('../hooks/ponytail-on-stimulants-instructions.js');
const {
  buildContinuationPrompt,
  claimContinuation,
  collectGitEvidence,
  compactEvidence,
  createTurnState,
  maxContinuations,
  recordToolCall,
  recordToolResult,
  shouldRunCompletionPass,
  summarizeTrackedEvidence,
} = require('../completion-gate/index.js');
const { createJevJudge } = require('../completion-gate/jev.js');
const { recordRecap, rememberAnswer } = require('../completion-gate/recap.js');

export { filterSkillBodyForMode };
export const readDefaultMode = getDefaultMode;
export const readQuietStartup = getQuietStartup;

const COMMAND = 'ponytail-on-stimulants';
const MODE_ENTRY = 'ponytail-on-stimulants-mode';
const MODE_LIST = RUNTIME_MODES.join('|');

export function resolveSessionMode(entries, fallbackMode = DEFAULT_MODE) {
  const fallback = normalizeMode(fallbackMode) || DEFAULT_MODE;
  if (!Array.isArray(entries)) return fallback;
  for (let index = entries.length - 1; index >= 0; index -= 1) {
    const entry = entries[index];
    if (!entry || entry.type !== 'custom' || entry.customType !== MODE_ENTRY) continue;
    const mode = normalizeMode(entry.data && entry.data.mode);
    if (mode) return mode;
  }
  return fallback;
}

export function completePonytailArgs(prefix) {
  const typed = String(prefix || '').trimStart();
  const values = [...RUNTIME_MODES, 'status', ...RUNTIME_MODES.map((mode) => `default ${mode}`)];
  const matches = values.filter((value) => value.startsWith(typed));
  return matches.length ? matches.map((value) => ({ value, label: value })) : null;
}

function bareCommand(fallback, currentMode) {
  if (currentMode && currentMode !== 'off') return { type: 'status' };
  return { type: 'set-mode', mode: fallback === 'off' ? DEFAULT_MODE : fallback };
}

export function parsePonytailCommand(text, defaultMode = DEFAULT_MODE, currentMode = null) {
  const fallback = normalizeMode(defaultMode) || DEFAULT_MODE;
  const normalizedText = String(text || '').trim().toLowerCase();
  if (!normalizedText) return bareCommand(fallback, currentMode);

  const [primary, secondary] = normalizedText.split(/\s+/);
  if (primary === 'status') return { type: 'status' };
  if (primary === 'default') {
    const mode = normalizeMode(secondary);
    return mode ? { type: 'set-default', mode } : { type: 'invalid', reason: 'invalid-default-mode' };
  }
  const mode = normalizeMode(primary);
  return mode ? { type: 'set-mode', mode } : { type: 'invalid', reason: 'invalid-mode', mode: primary };
}

export { writeDefaultMode };

function messageText(message) {
  if (typeof message?.content === 'string') return message.content;
  if (!message || !Array.isArray(message.content)) return '';
  return message.content
    .filter((part) => part && part.type === 'text')
    .map((part) => part.text || '')
    .join('\n');
}

function compactJevEvidence(tracked, git) {
  return {
    git_available: git.available,
    git_error_count: git.errors.length,
    changed_file_count: git.changedFiles.length,
    diff_check_failed: git.diffCheckFailed,
    introduced_todo_count: git.introducedTodos.length,
    unresolved_tool_error_count: tracked.toolErrors.length,
    recent_tools: tracked.recentTools.slice(-10).map(({ tool, status }) => ({ tool, status })),
    repeated_action_count: tracked.repeatedActions.length,
    repeated_failure_count: tracked.repeatedFailures.length,
  };
}

export default function ponytailOnStimulantsExtension(pi, options = {}) {
  let currentMode = DEFAULT_MODE;
  let configuredDefaultMode = getDefaultMode();
  let hideStatus = getHideStatus();
  let isActive = false;
  let lastCtx = null;
  let turnState = createTurnState('');
  let finalAssistantMessage = '';
  let queuedPass = null;
  const jevJudge = options.jevJudge === undefined ? createJevJudge() : options.jevJudge;

  function statusSurface(ctx) {
    if (ctx) lastCtx = ctx;
    const context = ctx || lastCtx;
    if (!context) return null;
    const ui = context.ui;
    if (!ui || typeof ui.setStatus !== 'function') return null;
    try {
      const theme = ui.theme;
      if (!theme || typeof theme.fg !== 'function') return null;
      return { theme, ui };
    } catch (_) {
      // Some headless UI proxies have no initialized theme.
      return null;
    }
  }

  function syncStatus(ctx) {
    const surface = statusSurface(ctx);
    if (!surface) return;
    const { theme, ui } = surface;
    if (hideStatus || currentMode === 'off') {
      ui.setStatus(COMMAND, undefined);
      return;
    }
    const icons = { focused: '🎯', 'full-send': '⚡', feral: '🔥' };
    const indicator = isActive ? theme.fg('accent', '●') : theme.fg('dim', '○');
    const icon = icons[currentMode] || '';
    const pass = queuedPass
      ? theme.fg('muted', ` · pass ${queuedPass.pass}/${queuedPass.maximum}`)
      : '';
    ui.setStatus(
      COMMAND,
      `${indicator} 🐴 ${theme.fg('muted', 'stimulants: ')}${theme.fg('text', `${icon} ${currentMode.toUpperCase()}`)}${pass}`,
    );
  }

  function setMode(mode, ctx) {
    const normalized = normalizeMode(mode);
    if (!normalized) return;
    currentMode = normalized;
    pi.appendEntry(MODE_ENTRY, { mode: normalized });
    syncStatus(ctx);
    ctx?.ui?.notify?.(`Ponytail on Stimulants mode set to ${normalized}.`, 'info');
  }

  function sendSkillCommand(skillName, args, ctx) {
    const tail = String(args || '').trim();
    const message = tail ? `${skillName} ${tail}` : skillName;
    if (ctx?.isIdle?.() === false) {
      pi.sendUserMessage(message, { deliverAs: 'followUp', expandPromptTemplates: true });
      ctx?.ui?.notify?.(`${skillName} queued as follow-up.`, 'info');
      return;
    }
    pi.sendUserMessage(message, { expandPromptTemplates: true });
  }

  function notify(ctx, message, level = 'info') {
    if (ctx && ctx.ui && typeof ctx.ui.notify === 'function') ctx.ui.notify(message, level);
  }

  function persistDefault(mode, ctx) {
    try {
      const written = writeDefaultMode(mode);
      if (!written) return;
      configuredDefaultMode = getDefaultMode();
      const message = configuredDefaultMode === written
        ? `Default mode set to ${written}.`
        : `Saved ${written}, but an environment override keeps ${configuredDefaultMode}.`;
      notify(ctx, message);
    } catch (error) {
      notify(ctx, `Failed to save default mode: ${error.message}`, 'error');
    }
  }

  function handleCommand(args, ctx) {
    const parsed = parsePonytailCommand(args, configuredDefaultMode, currentMode);
    if (parsed.type === 'status') {
      notify(ctx, `Ponytail on Stimulants: current ${currentMode} • default ${configuredDefaultMode}`);
      return;
    }
    if (parsed.type === 'set-default') return persistDefault(parsed.mode, ctx);
    if (parsed.type === 'set-mode') return setMode(parsed.mode, ctx);
    notify(ctx, 'Unknown or unsupported Ponytail on Stimulants mode.', 'warning');
  }

  pi.registerCommand(COMMAND, {
    description: `Set mode: ${MODE_LIST}. Commands: status, default <mode>`,
    getArgumentCompletions: completePonytailArgs,
    handler: handleCommand,
  });

  for (const suffix of ['review', 'audit', 'gain', 'debt', 'help']) {
    const name = `${COMMAND}-${suffix}`;
    pi.registerCommand(name, {
      description: `Run /skill:${name}`,
      handler: (args, ctx) => sendSkillCommand(`/skill:${name}`, args, ctx),
    });
  }

  pi.on('input', async (event, ctx) => {
    const source = event && event.source;
    if (source === 'extension') return;
    const text = event && event.text;
    turnState = createTurnState(text || '');
    finalAssistantMessage = '';
    queuedPass = null;
    syncStatus(ctx);
    if (currentMode === 'off') return;
    if (isDeactivationCommand(text)) setMode('off', ctx);
  });

  function sessionEntries(ctx) {
    if (!ctx || !ctx.sessionManager) return [];
    const manager = ctx.sessionManager;
    if (typeof manager.getBranch === 'function') return manager.getBranch();
    if (typeof manager.getEntries === 'function') return manager.getEntries();
    return [];
  }

  function restoreSession(ctx) {
    configuredDefaultMode = getDefaultMode();
    hideStatus = getHideStatus();
    currentMode = resolveSessionMode(sessionEntries(ctx), configuredDefaultMode);
    turnState = createTurnState('');
    finalAssistantMessage = '';
    queuedPass = null;
    isActive = false;
    syncStatus(ctx);
  }

  pi.on('session_start', async (_event, ctx) => {
    restoreSession(ctx);
    if (!getQuietStartup()) notify(ctx, `Ponytail on Stimulants loaded: ${currentMode}`);
  });

  // OMP uses switch/branch events; both hosts use tree navigation.
  for (const name of ['session_tree', 'session_switch', 'session_branch']) {
    pi.on(name, async (_event, ctx) => restoreSession(ctx));
  }

  pi.on('agent_start', async (_event, ctx) => {
    isActive = true;
    syncStatus(ctx);
  });

  pi.on('agent_end', async (event, ctx) => {
    isActive = false;
    syncStatus(ctx);
    const lastAssistant = event?.messages?.filter((message) => message.role === 'assistant').at(-1);
    if (ctx?.signal?.aborted || ['aborted', 'error'].includes(lastAssistant?.stopReason)) return;
    try {
      if (!await handleSettlement(ctx)) await recapSettledTurn(ctx);
    } catch (_) {
      // Completion gating is advisory and fail-open; it must never trap a session.
    }
  });

  function recapSettledTurn(ctx) {
    // pi-subagents children are summarized by the parent turn's recap.
    if (process.env.PI_SUBAGENT_CHILD === '1') return null;
    const session = ctx?.sessionManager?.getSessionId?.() || 'default';
    return recordRecap({
      harness: options.harness || 'pi',
      cwd: ctx && ctx.cwd,
      session,
      state: turnState,
      reply: finalAssistantMessage,
      exec: (command, args, execOptions) => pi.exec(command, args, execOptions),
    });
  }

  pi.on('message_end', async (event) => {
    if (event?.message?.role === 'assistant') finalAssistantMessage = messageText(event.message);
  });

  pi.on('tool_execution_start', async (event) => {
    recordToolCall(
      turnState,
      event?.toolName || 'unknown',
      event?.args || {},
      event?.toolCallId,
    );
  });

  pi.on('tool_execution_end', async (event) => {
    recordToolResult(
      turnState,
      event?.toolName || 'unknown',
      {},
      Boolean(event?.isError),
      event?.toolCallId,
    );
  });

  function settlementIsStale(state, mode) {
    return turnState !== state || currentMode !== mode;
  }

  function jevState(state, message, tracked, git) {
    return {
      requestMetadata: {
        hasTask: Boolean(state.prompt.trim()),
        taskLength: state.prompt.length,
      },
      responseMetadata: {
        claimedComplete: /\b(done|complete|completed|fixed|implemented|verified)\b/i.test(message),
        reportedBlocker: /\b(blocked|blocker|unable|could not)\b/i.test(message),
        responseLength: message.length,
      },
      changedFiles: git.changedFiles,
      verification: tracked.recentTools
        .filter((item) => item.tool === 'bash' && item.status === 'passed')
        .map((item) => `bash:${item.fingerprint}`),
      deterministicEvidence: compactJevEvidence(tracked, git),
      unresolvedErrors: tracked.toolErrors.map((item) => `${item.tool}:${item.fingerprint}`),
    };
  }

  async function judgeSettlement(state, mode, message, tracked, git) {
    if (!jevJudge || mode !== 'feral' || state.continuations < 1) return null;
    return jevJudge(jevState(state, message, tracked, git));
  }

  function recordedJev(jev) {
    if (!jev) return null;
    return {
      verdict: jev.verdict,
      model: jev.model,
      reason: jev.reason,
      latencyMs: jev.latencyMs,
      usage: jev.usage,
      answers: jev.answers,
    };
  }

  // Resolves false only when the turn settled without queueing a pass.
  async function handleSettlement(ctx) {
    const state = turnState;
    const mode = currentMode;
    const message = finalAssistantMessage;
    const tracked = summarizeTrackedEvidence(state);
    if (!shouldRunCompletionPass(mode, state, { tracked })) return false;
    const git = await collectGitEvidence(
      (command, args, execOptions) => pi.exec(command, args, execOptions),
      ctx && ctx.cwd,
    );
    if (ctx?.signal?.aborted || settlementIsStale(state, mode)) return true;
    const evidence = { tracked, git };
    const jev = await judgeSettlement(state, mode, message, tracked, git);
    if (settlementIsStale(state, mode)) return true;
    const maximum = maxContinuations(mode);
    const prompt = buildContinuationPrompt({
      mode,
      pass: state.continuations + 1,
      maximum,
      evidence,
      jev,
    });
    if (!claimContinuation(state, prompt, maximum)) return false;
    rememberAnswer(state, message);
    pi.appendEntry('ponytail-on-stimulants-completion-pass', {
      mode,
      pass: state.continuations,
      evidence: compactEvidence(evidence),
      jev: recordedJev(jev),
    });
    // agent_end handlers run before Pi decides whether queued follow-ups remain.
    // Queueing here keeps RPC's public agent_settled event truthful: it fires only
    // after every bounded completion pass, never between the original turn and a pass.
    pi.sendUserMessage(prompt, { deliverAs: 'followUp' });
    queuedPass = { pass: state.continuations, maximum };
    syncStatus(ctx);
    notify(ctx, `Completion pass ${state.continuations}/${maximum} queued.`);
    return true;
  }

  pi.on('before_agent_start', async (event) => {
    const sections = event?.systemPromptOptions?.sections;
    if (currentMode === 'off') {
      if (sections) delete sections[COMMAND];
      return;
    }
    const instructions = getPonytailInstructions(currentMode);
    // Pi can track section deltas unless an earlier extension forced an opaque
    // prompt, in which case the host ignores sections and we must append below.
    if (sections && typeof sections === 'object' && event.systemPromptOptions.forceSystemPrompt === undefined) {
      sections[COMMAND] = instructions;
      return;
    }
    // OMP owns an array of prompt parts; never stringify it into comma-separated text.
    if (Array.isArray(event?.systemPrompt)) {
      return { systemPrompt: [...event.systemPrompt, instructions] };
    }
    const base = event?.systemPrompt ? `${event.systemPrompt}\n\n` : '';
    return { systemPrompt: `${base}${instructions}` };
  });
}

# Upstream relationship

Canonical upstream: <https://github.com/DietrichGebert/ponytail>

Last reconciled version: `v4.10.0`

Last reconciled commit: `e3ba2aa6f1e6f0bc4d69eb09c9f0d0a93af56156`

Ponytail on Stimulants is a soft fork. Upstream is the authority for host protocol maintenance and installation plumbing; this fork is the authority for completion behavior, fork identity, Agent Plugins packaging, and its evaluation/gating code.

## Selective maintenance review

Reviewed upstream **v5.2.0**, commit `2961b52`, on 2026-10-14/15. Adopted useful
host-protocol, subprocess-safety, skill-review and benchmark-correctness fixes;
see [the compatibility review](docs/harness-compatibility.md) for sources and
explicit exclusions. This was **not** a merge: the reconciled base above stays
unchanged so future sync checks do not falsely assume upstream history is contained.

Current official Codex packaging supports the portable manifest plus its native
compatibility overlay; retain our Agent Plugins schema rather than importing the
older upstream schema-removal workaround. Completion semantics and fork identity
remain unchanged.

## Expected ownership

Mostly upstream-owned, reconciled rather than rewritten:

- host hook protocols and native adapter maintenance;
- installation plumbing and platform-specific fixes;
- packaging utilities that are not identity-specific;
- inherited correctness/safety benchmark machinery.

Intentionally fork-owned conflict surfaces:

- `AGENTS.md` and static rule copies;
- `skills/ponytail-on-stimulants*/` and generated `.openclaw/skills/` copies;
- `completion-gate/` and its Pi / Oh My Pi integration;
- `.omp-plugin/` marketplace packaging and `package.json` `omp.extensions`;
- `benchmarks/completion/`;
- fork package, plugin, command, skill, runtime-state, and branding identities;
- `README.md`, `UPSTREAM.md`, `RELEASE.md`;
- upstream-sync and fork release workflows.

Historical files under `benchmarks/results/` are upstream heritage. Keep their original claims and identify them as upstream evidence; do not silently relabel them as fork results.

## Reconciliation procedure

1. Ensure the worktree is clean.
2. `git fetch upstream main` and inspect upstream changelog/diff since the recorded commit.
3. Run `scripts/sync-upstream.sh --check` for a disposable-worktree conflict and structural check.
4. Create a temporary branch from current `main`; merge `upstream/main` with `--no-commit`.
5. Let upstream win for host protocol fixes. Reconcile behavioral and identity files consciously using the ownership list above; never accept upstream prompt semantics blindly.
6. Regenerate OpenClaw copies: `node scripts/build-openclaw-skills.js`.
7. Run `npm run check`, `npm test`, `npm run test:completion`, `python3 benchmarks/agentic/run.py --selftest`, and `python3 benchmarks/agentic/complete.py --selftest-offline`.
8. Update the version/commit at the top of this file and open a review PR. Do not auto-merge.

The scheduled `.github/workflows/upstream-sync.yml` follows the same policy on an automation branch. It opens a PR only after a conflict-free reconciliation and green validation. Conflicts create an issue and no branch is pushed to `main`.

## Known conflict classes

- upstream mode semantics vs the fork's `focused`/`full-send`/`feral` contract;
- upstream ladder-only prompt vs fork completion loop and stopping contract;
- globally named `ponytail` packages, skills, commands, files, and state vs coexistence-safe fork names;
- upstream code-size benchmark messaging vs fork completion metrics;
- Pi lifecycle handling, where this fork adds a bounded `agent_settled` continuation pass;
- Oh My Pi marketplace/extension packaging, which this fork keeps first-class and distinct from upstream `ponytail`.

## Release relationship

A fork release records this upstream base, retains the MIT notice, uses only fork package/marketplace identities, and follows [RELEASE.md](RELEASE.md). Upstream tags and package versions do not become fork releases automatically.
